sap.ui.define(["sap/ui/test/opaQunit","./pages/Home","./pages/Browser","./pages/NotFound","./pages/App"],function(e){"use strict";QUnit.module("NotFound");e("Should see the resource not found page when changing to an invalid hash",function(e,o,n){e.iStartMyApp();o.onTheBrowser.iChangeTheHashToSomethingInvalid();n.onTheNotFoundPage.iShouldSeeResourceNotFound()});e("Clicking the 'Show my worklist' link on the 'Resource not found' page should bring me back to the worklist",function(e,o,n){o.onTheAppPage.iWaitUntilTheAppBusyIndicatorIsGone();o.onTheNotFoundPage.iPressTheNotFoundShowHomeLink();n.onTheHomePage.iShouldSeeTheTable()});e("Should see the not found text for no search results",function(e,o,n){o.onTheHomePage.iSearchForSomethingWithNoResults();n.onTheHomePage.iShouldSeeTheNoDataTextForNoSearchResults()});e("Clicking the back button should take me back to the not found page",function(e,o,n){o.onTheBrowser.iPressOnTheBackwardsButton();n.onTheNotFoundPage.iShouldSeeResourceNotFound();n.iTeardownMyApp()});e("Should see the 'Object not found' page if an invalid object id has been called",function(e,o,n){e.iStartMyApp({hash:"ZWCP_C_BP_INFO/SomeInvalidObjectId"});n.onTheNotFoundPage.iShouldSeeObjectNotFound()});e("Clicking the 'Show my worklist' link on the 'Object not found' page should bring me back to the worklist",function(e,o,n){o.onTheAppPage.iWaitUntilTheAppBusyIndicatorIsGone();o.onTheNotFoundPage.iPressTheObjectNotFoundShowHomeLink();n.onTheHomePage.iShouldSeeTheTable();n.iTeardownMyApp()})});